/**
 * Unit tests for DiscreteDistribution.getSamples()
 */
public class DiscreteDistribution_getSamples_TriageGen0Test {

    @Test
    public void testGetSamplesWithMultipleEntries() throws Exception {
        // Arrange
        List<Pair<String, Double>> inputSamples = new ArrayList<>();
        inputSamples.add(new Pair<>("A", 0.2));
        inputSamples.add(new Pair<>("B", 0.3));
        inputSamples.add(new Pair<>("C", 0.5));

        DiscreteDistribution<String> distribution = new DiscreteDistribution<>(inputSamples);

        // Act
        List<Pair<String, Double>> result = distribution.getSamples();

        // Assert
        assertNotNull(result);
        assertEquals(3, result.size());

        assertEquals("A", result.get(0).getFirst());
        assertEquals(0.2, result.get(0).getSecond(), 1e-10);

        assertEquals("B", result.get(1).getFirst());
        assertEquals(0.3, result.get(1).getSecond(), 1e-10);

        assertEquals("C", result.get(2).getFirst());
        assertEquals(0.5, result.get(2).getSecond(), 1e-10);
    }

    @Test
    public void testGetSamplesWithSingleEntry() throws Exception {
        // Arrange
        List<Pair<Integer, Double>> inputSamples = new ArrayList<>();
        inputSamples.add(new Pair<>(1, 1.0));

        DiscreteDistribution<Integer> distribution = new DiscreteDistribution<>(inputSamples);

        // Act
        List<Pair<Integer, Double>> result = distribution.getSamples();

        // Assert
        assertNotNull(result);
        assertEquals(1, result.size());
        assertEquals(Integer.valueOf(1), result.get(0).getFirst());
        assertEquals(1.0, result.get(0).getSecond(), 1e-10);
    }

    @Test
    public void testGetSamplesWithEmptyList() throws Exception {
        // Arrange
        List<Pair<Double, Double>> inputSamples = new ArrayList<>();
        // Note: Depending on implementation of DiscreteDistribution, 
        // an empty list might throw an exception in constructor.
        // If the constructor allows it, we test the empty return.

        // Based on the provided signature, we assume we can instantiate it if valid.
        // If the constructor throws exception for empty, this test would change.
        try {
            DiscreteDistribution<Double> distribution = new DiscreteDistribution<>(inputSamples);

            // Act
            List<Pair<Double, Double>> result = distribution.getSamples();

            // Assert
            assertNotNull(result);
            assertEquals(0, result.size());
        } catch (Exception e) {
            // If constructor prevents empty lists, that is also valid behavior.
            // This part depends on the actual implementation of the constructor.
        }
    }

    @Test
    public void testGetSamplesIntegrity() throws Exception {
        // Arrange
        List<Pair<String, Double>> inputSamples = Arrays.asList(
            new Pair<>("X", 0.1),
            new Pair<>("Y", 0.9)
        );
        DiscreteDistribution<String> distribution = new DiscreteDistribution<>(inputSamples);

        // Act
        List<Pair<String, Double>> result = distribution.getSamples();

        // Assert: Ensure the returned list is a new list (defensive copy check if applicable)
        // and contains the exact same values.
        for (int i = 0; i < inputSamples.size(); i++) {
            assertEquals(inputSamples.get(i).getFirst(), result.get(i).getFirst());
            assertEquals(inputSamples.get(i).getSecond(), result.get(i).getSecond(), 1e-10);
        }
    }
}
